import { readFile, writeFile, readdir } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";
const root = fileURLToPath(new URL("../", import.meta.url));
const runtime = await readFile(
  path.join(root, "scripts/theme-kit/runtime.js"),
  "utf8",
);
const check = process.argv.includes("--check");
for (const directory of (await readdir(root))
  .filter((name) => name.startsWith("theme-"))
  .sort()) {
  const config = JSON.parse(
    await readFile(path.join(root, directory, "themes.json"), "utf8"),
  );
  const result =
    "// Generated by scripts/build-theme-plugins.mjs; edit themes.json or scripts/theme-kit/runtime.js.\n" +
    runtime +
    "\nexport async function activate(ctx) {\n  const themes = " +
    JSON.stringify(config, null, 2) +
    ";\n  for (const config of themes) await activateTheme(ctx, config);\n}\n";
  const entry = path.join(root, directory, "index.js");
  if (check) {
    if ((await readFile(entry, "utf8")) !== result)
      throw new Error(`${directory}: regenerate index.js`);
  } else await writeFile(entry, result);
  console.log(directory);
}
